create table public.crop_stands(id uuid primary key default gen_random_uuid(),farm_id uuid not null references public.farms(id)on delete cascade,campaign_id uuid not null references public.campaigns(id)on delete cascade,lot_id uuid not null references public.lots(id)on delete restrict,crop text not null,hectares numeric(12,2)not null check(hectares>0),sowing_date date not null,phenological_stage text not null,condition text not null check(condition in('muy_buena','buena','regular','mala')),target_yield_kg_ha numeric(12,2)not null,projected_yield_kg_ha numeric(12,2)not null,next_action text,next_action_date date,executed_cost_ars numeric(18,2)not null default 0,committed_cost_ars numeric(18,2)not null default 0,notes text,created_by uuid not null references public.profiles(id),unique(campaign_id,lot_id,crop));
create table public.inventory_batches(id uuid primary key default gen_random_uuid(),farm_id uuid not null references public.farms(id)on delete cascade,product text not null,origin_campaign text not null,origin_lot text,storage_location text not null,opening_tons numeric(16,3)not null check(opening_tons>=0),purchased_tons numeric(16,3)not null default 0,sold_tons numeric(16,3)not null default 0,consumed_tons numeric(16,3)not null default 0,reserved_tons numeric(16,3)not null default 0,available_tons numeric(16,3)generated always as(opening_tons+purchased_tons-sold_tons-consumed_tons-reserved_tons)stored,price_ars_ton numeric(16,2)not null,quality_note text,created_by uuid not null references public.profiles(id),check(sold_tons+consumed_tons+reserved_tons<=opening_tons+purchased_tons));
create table public.financial_commitments(id uuid primary key default gen_random_uuid(),farm_id uuid not null references public.farms(id)on delete cascade,due_date date not null,direction text not null check(direction in('pagar','cobrar')),concept text not null,counterparty text,amount_ars numeric(18,2)not null check(amount_ars>0),status text not null default 'pendiente'check(status in('pendiente','cumplido','anulado')),created_by uuid not null references public.profiles(id));
alter table public.crop_stands enable row level security;alter table public.inventory_batches enable row level security;alter table public.financial_commitments enable row level security;
create policy crop_stands_access on public.crop_stands for all to authenticated using(public.can_access_farm(farm_id))with check(public.can_manage_farm(farm_id));create policy inventory_access on public.inventory_batches for all to authenticated using(public.can_access_farm(farm_id))with check(public.can_manage_farm(farm_id));create policy commitments_access on public.financial_commitments for all to authenticated using(public.can_access_farm(farm_id))with check(public.can_manage_farm(farm_id));
create view public.farm_current_position with(security_invoker=true)as select f.id farm_id,f.name farm_name,coalesce((select sum(hectares)from public.crop_stands c where c.farm_id=f.id),0)winter_crop_ha,coalesce((select sum(opening_tons+purchased_tons-sold_tons-consumed_tons)from public.inventory_batches i where i.farm_id=f.id),0)physical_stock_tons,coalesce((select sum(available_tons)from public.inventory_batches i where i.farm_id=f.id),0)available_stock_tons,coalesce((select sum(reserved_tons)from public.inventory_batches i where i.farm_id=f.id),0)reserved_stock_tons,coalesce((select sum(available_tons*price_ars_ton)from public.inventory_batches i where i.farm_id=f.id),0)stock_value_ars,coalesce((select sum(amount_ars)from public.financial_commitments c where c.farm_id=f.id and direction='cobrar'and status='pendiente'),0)receivables_ars,coalesce((select sum(amount_ars)from public.financial_commitments c where c.farm_id=f.id and direction='pagar'and status='pendiente'),0)payables_ars,coalesce((select count(*)from public.field_operations o where o.farm_id=f.id and o.status='planificada'and o.operation_date<=current_date+30),0)work_orders_30d from public.farms f where f.active;grant select on public.farm_current_position to authenticated;
